// Procedural, deformable 2D terrain for UAZ TRIAL.
export const STEP = 4;
export const PX_PER_M = 60;
export const START_X = 210;
export const BASE_Y = 548;

export function mulberry32(a) {
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
export const lerp = (a, b, t) => a + (b - a) * t;
export const smoothstep = (a, b, x) => {
  const t = clamp((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
};

export class Terrain {
  constructor(seed = 1337) {
    this.seed = seed;
    this.rng = mulberry32(seed);
    this.cap = 26000;
    this.heights = new Float32Array(this.cap);
    this.original = new Float32Array(this.cap);
    this.softness = new Float32Array(this.cap);
    this.disturb = new Float32Array(this.cap);
    this.count = 0;
    this.generatedTo = 0;
    this.nextFeatureX = 760;
    this.decorTo = 260;
    this.trees = [];
    this.rocks = [];
    this.bushes = [];
    this.lastSmooth = 0;
    this.mudPits = [];
    this.fillTo(Math.ceil(2400 / STEP) + 4);
    this.generateUntil(5600);
  }

  ensure(index) {
    if (index < this.cap) return;
    let cap = this.cap;
    while (cap <= index) cap *= 2;
    const grow = (arr) => {
      const next = new Float32Array(cap);
      next.set(arr);
      return next;
    };
    this.heights = grow(this.heights);
    this.original = grow(this.original);
    this.softness = grow(this.softness);
    this.disturb = grow(this.disturb);
    this.cap = cap;
  }

  baseHeight(x) {
    let h =
      BASE_Y +
      Math.sin(x * 0.00165 + 0.7) * 18 +
      Math.sin(x * 0.0049 + 2.2) * 7 +
      Math.sin(x * 0.00062 + 1.1) * 26;
    // flat, safe launch pad
    h = lerp(BASE_Y, h, smoothstep(300, 720, x));
    return h;
  }

  fillTo(index) {
    this.ensure(index + 6);
    while (this.count <= index) {
      const x = this.count * STEP;
      const h = this.baseHeight(x);
      this.heights[this.count] = h;
      this.original[this.count] = h;
      this.softness[this.count] = 0;
      this.disturb[this.count] = 0;
      this.count++;
    }
    this.generatedTo = (this.count - 1) * STEP;
  }

  makeFeature(start) {
    const r = this.rng;
    const meters = start / PX_PER_M;
    const diff = clamp((meters - 40) / 1000, 0, 1);
    const roll = r();
    let type = "hill";
    if (meters < 90) {
      type = roll < 0.62 ? "hill" : roll < 0.86 ? "ruts" : "mud";
    } else if (meters < 260) {
      type = roll < 0.42 ? "hill" : roll < 0.64 ? "ruts" : roll < 0.84 ? "mud" : "rock";
    } else {
      if (roll < 0.28) type = "hill";
      else if (roll < 0.47) type = "steep";
      else if (roll < 0.68) type = "mud";
      else if (roll < 0.82) type = "ruts";
      else if (roll < 0.94) type = "rock";
      else type = "ramp";
    }

    const scale = 1 + diff * 0.55;
    const f = { type, start, width: 320, amp: 60, soft: 0, shape: "smooth" };

    switch (type) {
      case "hill": {
        f.width = 300 + r() * 320;
        f.amp = (34 + r() * 88) * scale;
        f.amp *= r() < 0.42 ? -1 : 1;
        if (f.amp < 0) f.amp *= 0.8;
        break;
      }
      case "steep": {
        f.width = 270 + r() * 240;
        f.amp = (120 + r() * 110) * (1 + diff * 0.25);
        f.shape = "asym";
        break;
      }
      case "mud": {
        f.width = 210 + r() * 210 + diff * 60;
        f.amp = 24 + r() * 26 + diff * 18;
        f.soft = 0.72 + r() * 0.28;
        f.shape = "pit";
        break;
      }
      case "ruts": {
        f.width = 330 + r() * 360;
        f.amp = 6 + r() * 10 + diff * 6;
        f.soft = 0.32 + r() * 0.24;
        f.shape = "rut";
        break;
      }
      case "rock": {
        f.width = 70 + r() * 95;
        f.amp = (16 + r() * 30) * (1 + diff * 0.5);
        f.shape = "rock";
        break;
      }
      case "ramp": {
        f.width = 150 + r() * 150;
        f.amp = 52 + r() * 66;
        f.shape = "ramp";
        break;
      }
    }
    return f;
  }

  applyFeature(f) {
    const startIdx = Math.round(f.start / STEP);
    const n = Math.max(4, Math.round(f.width / STEP));
    const endIdx = startIdx + n;
    this.ensure(endIdx + 8);
    this.fillTo(endIdx + 4);

    const mudPit = f.type === "mud";
    if (mudPit) {
      this.mudPits.push({ x: f.start + f.width * 0.5, w: f.width, depth: f.amp });
    }

    for (let i = 0; i <= n; i++) {
      const t = i / n;
      const idx = startIdx + i;
      if (idx >= this.count) break;
      let w;
      if (f.shape === "pit") {
        w = Math.pow(Math.sin(Math.PI * t), 0.7);
      } else if (f.shape === "asym") {
        // gentle approach, long crest, steep back side
        w = Math.sin(Math.PI * Math.pow(t, 0.78));
        w = Math.pow(w, 1.15);
      } else if (f.shape === "ramp") {
        w = t < 0.72 ? smoothstep(0, 0.72, t) : 1 - smoothstep(0.72, 1, t) * 0.92;
        w = Math.pow(w, 1.2);
      } else if (f.shape === "rock") {
        w = Math.pow(Math.sin(Math.PI * t), 1.9);
      } else if (f.shape === "rut") {
        const ripple = 0.55 + 0.45 * Math.sin(t * Math.PI * 6 + f.start * 0.01);
        w = Math.pow(Math.sin(Math.PI * t), 1.2) * ripple;
      } else {
        w = Math.sin(Math.PI * t) ** 2;
      }

      const dir = f.amp < 0 ? -1 : 1;
      this.heights[idx] -= f.amp * w; // positive amp raises terrain

      if (f.soft > 0) {
        const s = f.soft * Math.pow(Math.sin(Math.PI * t), 0.42);
        this.softness[idx] = Math.max(this.softness[idx], s);
      }
      if (f.type === "rock") {
        this.softness[idx] = 0;
      }
      void dir;
    }

    // mud wallows get extra soft banks so they read clearly
    if (mudPit) {
      for (let i = -8; i <= n + 8; i++) {
        const idx = startIdx + i;
        if (idx < 1 || idx >= this.count) continue;
        const edge = 1 - Math.min(1, Math.abs(i - n / 2) / (n / 2 + 10));
        this.softness[idx] = Math.max(this.softness[idx], 0.22 * edge);
      }
    }
  }

  smoothNew() {
    const start = Math.max(2, this.lastSmooth);
    const end = this.count - 2;
    if (end - start < 8) return;

    // three-tap smoothing to remove harsh feature joins
    for (let i = start; i <= end; i++) {
      this.heights[i] = (this.heights[i - 1] + this.heights[i] * 2 + this.heights[i + 1]) * 0.25;
    }
    // forward slope limiter
    const maxD = 0.82 * STEP;
    for (let i = start; i <= end; i++) {
      const prev = this.heights[i - 1];
      this.heights[i] = clamp(this.heights[i], prev - maxD, prev + maxD);
    }
    // backward slope limiter
    for (let i = end; i >= start; i--) {
      const next = this.heights[i + 1];
      this.heights[i] = clamp(this.heights[i], next - maxD, next + maxD);
    }
    for (let i = start; i <= end; i++) this.original[i] = this.heights[i];
    this.lastSmooth = Math.max(start, end - 4);
  }

  generateUntil(xMax) {
    const target = xMax + 1400;
    while (this.nextFeatureX < target) {
      const f = this.makeFeature(this.nextFeatureX);
      this.applyFeature(f);
      const gap = 100 + this.rng() * 230 - clamp((this.nextFeatureX / PX_PER_M - 100) / 900, 0, 1) * 60;
      this.nextFeatureX = f.start + f.width + Math.max(65, gap);
      this.smoothNew();
    }
    // make sure ground exists a little beyond what was asked
    this.fillTo(Math.ceil(target / STEP));
    this.smoothNew();
    this.generateDecor(target);
  }

  generateDecor(untilX) {
    while (this.decorTo < untilX) {
      const gap = 110 + this.rng() * 300;
      this.decorTo += gap;
      const x = this.decorTo;
      if (x < 520) continue;
      const r = this.rng();
      const y = this.heightAt(x);
      if (r < 0.46) {
        const type = this.rng() < 0.55 ? "pine" : this.rng() < 0.7 ? "birch" : "dead";
        this.trees.push({
          x,
          y,
          type,
          h: 72 + this.rng() * 120,
          lean: (this.rng() - 0.5) * 0.16,
          seed: this.rng() * 1000,
        });
      } else if (r < 0.68) {
        this.bushes.push({ x, y, s: 0.7 + this.rng() * 0.9, seed: this.rng() * 1000 });
      } else if (r < 0.86) {
        this.rocks.push({
          x,
          y,
          s: 4 + this.rng() * 13,
          rot: this.rng() * Math.PI,
          seed: this.rng() * 1000,
        });
      }
    }
  }

  idx(x) {
    const i = Math.round(x / STEP);
    return i < 0 ? 0 : i >= this.count ? this.count - 1 : i;
  }

  heightAt(x) {
    const f = x / STEP;
    let i = Math.floor(f);
    if (i < 0) i = 0;
    if (i >= this.count - 1) return this.heights[this.count - 1];
    const t = f - i;
    return this.heights[i] + (this.heights[i + 1] - this.heights[i]) * t;
  }

  slopeAt(x) {
    return (this.heightAt(x + 6) - this.heightAt(x - 6)) / 12;
  }

  normalAt(x) {
    const s = this.slopeAt(x);
    const len = Math.hypot(s, 1);
    return { x: -s / len, y: -1 / len, slope: s };
  }

  softnessAt(x) {
    const f = x / STEP;
    let i = Math.floor(f);
    if (i < 0) i = 0;
    if (i >= this.count - 1) return this.softness[this.count - 1];
    const t = f - i;
    return this.softness[i] + (this.softness[i + 1] - this.softness[i]) * t;
  }

  disturbAt(x) {
    const f = x / STEP;
    let i = Math.floor(f);
    if (i < 0) i = 0;
    if (i >= this.count - 1) return this.disturb[this.count - 1];
    const t = f - i;
    return this.disturb[i] + (this.disturb[i + 1] - this.disturb[i]) * t;
  }

  // dig a rut under a spinning/sinking wheel
  deform(x, amount, radius = 14) {
    const s = this.softnessAt(x);
    if (s < 0.08 || amount <= 0) return;
    const center = this.idx(x);
    const span = Math.max(2, Math.round(radius / STEP));
    for (let i = center - span; i <= center + span; i++) {
      if (i < 3 || i >= this.count - 1) continue;
      const d = Math.abs(i - center) / span;
      const falloff = Math.cos(d * Math.PI * 0.5) ** 2;
      const limit = this.original[i] - 58 * this.softness[i] - 4;
      this.heights[i] = Math.max(limit, this.heights[i] - amount * falloff);
      this.disturb[i] = Math.min(1.5, this.disturb[i] + amount * 0.07 * falloff);
    }
  }

  treeNear(x, dir, range = 520) {
    let best = null;
    let bestD = Infinity;
    for (const t of this.trees) {
      const dx = (t.x - x) * dir;
      if (dx < 60 || dx > range) continue;
      if (dx < bestD) {
        bestD = dx;
        best = t;
      }
    }
    return best;
  }
}

// Custom 2D rigid-body / raycast-suspension physics for the UAZ.
import { clamp, lerp, PX_PER_M } from "./terrain.js";

const G = 620;
const MASS = 1850;
const BODY_W = 252;
const BODY_H = 96;
const WHEELBASE = 192;
const ANCHOR_Y = 26;
const AIR_DRAG = 0.00034;

export const UPGRADE_MAX = 4;

export class Truck {
  constructor(terrain, upgrades = {}) {
    this.terrain = terrain;
    this.x = 210;
    this.y = terrain.heightAt(210) - 92;
    this.vx = 0;
    this.vy = 0;
    this.angle = 0;
    this.av = 0;
    this.mass = MASS;
    this.inertia = (MASS * (BODY_W * BODY_W + BODY_H * BODY_H)) / 12;
    this.wheels = [
      this.makeWheel(-WHEELBASE / 2, "rear"),
      this.makeWheel(WHEELBASE / 2, "front"),
    ];
    this.upgrades = { tires: 0, portal: 0, winch: 0, engine: 0, ...upgrades };
    this.setUpgrades(this.upgrades);
    this.input = { gas: 0, brake: 0, tilt: 0, diff: false };
    this.diffLocked = false;
    this.winch = {
      attached: false,
      anchor: null,
      ropeLen: 0,
      maxRope: 520,
      taut: false,
      type: "tree",
      force: 0,
    };
    this.airTime = 0;
    this.grounded = false;
    this.mud = 0;
    this.engineRpm = 0;
    this.impact = 0;
    this.spin = 0;
    this.tiltAmount = 0;
    this.winchCooldown = 0;
    this.anchorY = ANCHOR_Y;
    this.placeAt(this.x, this.angle);
  }

  makeWheel(x, id) {
    return {
      id,
      ax: x,
      ay: ANCHOR_Y,
      spin: 0,
      omega: 0,
      contact: false,
      N: 0,
      slip: 0,
      softness: 0,
      cx: 0,
      cy: 0,
      contactX: 0,
      contactY: 0,
      normal: { x: 0, y: -1 },
      tangent: { x: 1, y: 0 },
      load: 0,
      surface: "dirt",
      sink: 0,
    };
  }

  setUpgrades(u) {
    this.upgrades = { ...u };
    this.radius = 27 + u.tires * 4.6;
    this.restLen = 34 + u.portal * 5;
    this.travel = 27 + u.portal * 3.5;
    this.droop = 21 + u.portal * 2;
    this.engineMult = 1 + u.engine * 0.17;
    this.gripMult = 1 + u.tires * 0.055;
    this.mudFloat = 1 - u.tires * 0.12;
    this.winch.maxRope = 520 + u.winch * 85;
    this.winch.forceMax = 980000 + u.winch * 330000;
    this.winch.reelSpeed = 95 + u.winch * 32;
    this.winch.grip = 1;
  }

  placeAt(x, angle = 0) {
    this.terrain.generateUntil(x + 2000);
    this.x = x;
    this.y = this.terrain.heightAt(x) - (ANCHOR_Y + this.restLen + this.radius) - 3;
    this.angle = angle || Math.atan(this.terrain.slopeAt(x));
    this.vx = 0;
    this.vy = 0;
    this.av = 0;
    this.airTime = 0;
    this.winch.attached = false;
    for (const w of this.wheels) {
      w.omega = 0;
      w.spin = 0;
    }
  }

  get speed() {
    return Math.hypot(this.vx, this.vy);
  }

  get kmh() {
    return Math.hypot(this.vx, this.vy) * 0.06;
  }

  forwardSpeed() {
    return this.vx * Math.cos(this.angle) + this.vy * Math.sin(this.angle);
  }

  localToWorld(lx, ly) {
    const c = Math.cos(this.angle);
    const s = Math.sin(this.angle);
    return { x: this.x + lx * c - ly * s, y: this.y + lx * s + ly * c };
  }

  velocityAt(lx, ly) {
    const c = Math.cos(this.angle);
    const s = Math.sin(this.angle);
    const rx = lx * c - ly * s;
    const ry = lx * s + ly * c;
    return { x: this.vx - this.av * ry, y: this.vy + this.av * rx };
  }

  attachWinch(anchor, type = "tree") {
    if (this.winch.attached) {
      this.detachWinch();
      return false;
    }
    const wp = this.localToWorld(112, -12);
    const dist = Math.hypot(anchor.x - wp.x, anchor.y - wp.y);
    if (dist > this.winch.maxRope) return "too-far";
    this.winch.attached = true;
    this.winch.anchor = { x: anchor.x, y: anchor.y };
    this.winch.ropeLen = Math.min(dist + 8, this.winch.maxRope);
    this.winch.type = type;
    this.winch.taut = false;
    this.winch.force = 0;
    return true;
  }

  detachWinch() {
    this.winch.attached = false;
    this.winch.anchor = null;
    this.winch.force = 0;
    this.winch.taut = false;
  }

  applyForce(fx, fy, rx, ry) {
    this._fx += fx;
    this._fy += fy;
    this._torque += rx * fy - ry * fx;
  }

  update(dt, input) {
    this.input = input;
    const wasLocked = this.diffLocked;
    this.diffLocked = !!input.diff;
    if (this.diffLocked && !wasLocked) this.diffLocked = true;

    const t = this.terrain;
    const cos = Math.cos(this.angle);
    const sin = Math.sin(this.angle);
    const down = { x: -sin, y: cos };
    const fwd = { x: cos, y: sin };

    this._fx = 0;
    this._fy = 0;
    this._torque = 0;

    // gravity + aero drag
    this._fy += this.mass * G;
    this._fx -= this.vx * Math.abs(this.vx) * AIR_DRAG;
    this._fy -= this.vy * Math.abs(this.vy) * AIR_DRAG * 0.75;

    // driver tilt control
    this.tiltAmount = input.tilt || 0;
    if (this.tiltAmount) {
      this._torque += this.tiltAmount * this.inertia * 2.9;
    }

    const gas = clamp(input.gas || 0, 0, 1);
    const brake = clamp(input.brake || 0, 0, 1);
    const vF = this.forwardSpeed();
    let engine = 0;
    let braking = 0;
    if (gas > 0) engine = gas;
    if (brake > 0) {
      if (vF > 22) braking = brake;
      else if (vF > -170) engine = -0.62 * brake;
    }
    const diffBoost = this.diffLocked ? 1.1 : 1;
    const lowSpeedAssist = this.diffLocked && Math.abs(vF) < 90 ? 1.25 : 1;
    const baseTorque = 7400000 * this.engineMult * diffBoost * lowSpeedAssist;

    let contactCount = 0;
    let totalN = 0;
    let avgSlip = 0;
    let avgOmega = 0;
    let mudWheel = 0;

    for (const w of this.wheels) {
      const A = this.localToWorld(w.ax, w.ay);
      w.cx = A.x + down.x * this.restLen;
      w.cy = A.y + down.y * this.restLen;
      w.contact = false;
      w.N = 0;
      w.slip = 0;
      w.softness = 0;

      // ray-cast downward through the wheel
      let contact = false;
      let L = this.restLen;
      let groundX = A.x + down.x * this.restLen;
      if (down.y > 0.22) {
        const groundY = t.heightAt(groundX);
        const rawL = (groundY - this.radius - A.y) / down.y;
        if (rawL < this.restLen + this.droop) {
          L = clamp(rawL, 8, this.restLen + this.droop);
          contact = true;
        }
      }

      const C = { x: A.x + down.x * L, y: A.y + down.y * L };
      w.cx = C.x;
      w.cy = C.y;

      if (contact) {
        contactCount++;
        const n = t.normalAt(groundX);
        const slope = n.slope;
        const tlen = Math.hypot(1, slope);
        const tang = { x: 1 / tlen, y: slope / tlen };
        w.normal = { x: n.x, y: n.y };
        w.tangent = tang;
        w.contactX = C.x;
        w.contactY = C.y + this.radius;
        w.softness = t.softnessAt(groundX);

        // suspension spring + damper
        const comp = this.restLen - L;
        const vA = this.velocityAt(w.ax, w.ay);
        const vDown = vA.x * down.x + vA.y * down.y;
        const k = 47000 + this.upgrades.portal * 2600;
        const c = 10600;
        let N = k * comp + c * vDown;
        N = clamp(N, 0, 3200000);
        if (N > 0) {
          w.contact = true;
          w.N = N;
          w.load = N;
          totalN += N;
          this.applyForce(n.x * N, n.y * N, A.x - this.x, A.y - this.y);
        }

        // wheel angular speed
        const vC = this.velocityAt(w.cx - this.x, w.cy - this.y);
        const vT = vC.x * tang.x + vC.y * tang.y;
        const slip = w.omega * this.radius - vT;
        w.slip = slip;

        const soft = clamp(w.softness * this.mudFloat, 0, 1.2);
        let grip = 0.94 * this.gripMult;
        if (soft > 0.03) {
          grip = lerp(grip, Math.max(0.17, 0.72 - 0.6 * soft), clamp(soft * 1.5, 0, 1));
        }
        if (this.diffLocked) grip *= 1.62;
        const maxGrip = Math.max(0, N * grip);

        const slipForce = clamp(slip * 5400, -maxGrip, maxGrip);
        // friction acts on the chassis at the contact patch
        this.applyForce(
          tang.x * slipForce,
          tang.y * slipForce,
          w.contactX - this.x,
          w.contactY - this.y
        );

        // mud resistance / suction
        if (soft > 0.05) {
          mudWheel = Math.max(mudWheel, soft);
          const speedFactor = 0.1 + 0.055 * Math.min(1, Math.abs(vT) / 260);
          let dragMag = N * soft * speedFactor;
          if (Math.abs(vT) < 45) dragMag *= 1.3;
          if (this.diffLocked) dragMag *= 0.86;
          const dir = vT > 0 ? -1 : 1;
          this.applyForce(
            tang.x * dragMag * dir,
            tang.y * dragMag * dir,
            w.contactX - this.x,
            w.contactY - this.y
          );
          // spinning digs a rut
          if (Math.abs(slip) > 22) {
            const dig = (2.1 + Math.min(9.5, Math.abs(slip) / 38)) * soft * dt;
            t.deform(w.contactX, dig, this.radius * 0.85);
          }
          w.sink = Math.min(30, w.sink + soft * dt * 7);
        } else {
          w.sink = Math.max(0, w.sink - dt * 22);
          // light rolling resistance on hard ground
          const rr = Math.min(Math.abs(vT) * 240, N * 0.018);
          this.applyForce(
            -tang.x * Math.sign(vT) * rr,
            -tang.y * Math.sign(vT) * rr,
            w.contactX - this.x,
            w.contactY - this.y
          );
        }

        // engine / brake torque at the wheel
        const torqueCurve = 1 - 0.5 * Math.min(1, Math.abs(w.omega) / 55);
        const driveTorque = engine * baseTorque * Math.max(0.35, torqueCurve);
        let wheelTorque = driveTorque - slipForce * this.radius;
        if (braking > 0) {
          const bt = 6200000 * braking;
          const dv = Math.min(Math.abs(w.omega), (bt / (0.5 * 190 * this.radius * this.radius)) * dt);
          w.omega -= Math.sign(w.omega) * dv;
        }
        const Iw = 0.5 * 190 * this.radius * this.radius;
        w.omega += (wheelTorque / Iw) * dt;
        w.omega = clamp(w.omega, -60, 60);
        // a little rolling drag on the wheel itself
        w.omega *= 1 - 0.18 * dt;
        w.spin += w.omega * dt;
        avgSlip += Math.abs(slip);
        avgOmega += Math.abs(w.omega);
      } else {
        // free-spinning wheel in the air
        const torqueCurve = 1 - 0.5 * Math.min(1, Math.abs(w.omega) / 55);
        const driveTorque = engine * baseTorque * Math.max(0.35, torqueCurve);
        const Iw = 0.5 * 190 * this.radius * this.radius;
        w.omega += (driveTorque / Iw) * dt;
        if (braking > 0) {
          w.omega -= Math.sign(w.omega) * Math.min(Math.abs(w.omega), 10 * dt);
        }
        w.omega *= 1 - 1.1 * dt;
        w.omega = clamp(w.omega, -60, 60);
        w.spin += w.omega * dt;
        avgOmega += Math.abs(w.omega);
        w.sink = Math.max(0, w.sink - dt * 22);
      }
    }

    // locked diffs keep both axles spinning together
    if (this.diffLocked && this.wheels[0].contact && this.wheels[1].contact) {
      const avg = (this.wheels[0].omega + this.wheels[1].omega) * 0.5;
      for (const w of this.wheels) w.omega = lerp(w.omega, avg, 0.32);
    }

    this.grounded = contactCount > 0;
    if (this.grounded) {
      this.airTime = 0;
      this.spin = Math.min(1, this.spin + dt * 2);
    } else {
      this.airTime += dt;
      this.spin = Math.max(0, this.spin - dt * 1.6);
    }
    this.mud = Math.max(this.mud * (1 - dt * 0.06), mudWheel);
    this.engineRpm = clamp(avgOmega / 40, 0, 1.4);
    this.slip = contactCount ? avgSlip / contactCount : 0;

    // chassis hull collisions (corners, roof, rockers)
    const hull = [
      [-126, -64], [126, -64], [130, 43], [-130, 43],
      [0, -66], [0, 43], [-126, 20], [126, 20],
      [-68, 43], [68, 43], [-68, -65], [68, -65],
      [128, -20], [-128, -20],
    ];
    for (const [lx, ly] of hull) {
      const P = this.localToWorld(lx, ly);
      const gy = t.heightAt(P.x);
      const pen = P.y - gy;
      if (pen > 0) {
        const n = t.normalAt(P.x);
        const vp = this.velocityAt(lx, ly);
        const vn = vp.x * n.x + vp.y * n.y;
        let Fn = 175000 * pen - 5400 * vn;
        Fn = clamp(Fn, 0, 3600000);
        this.applyForce(n.x * Fn, n.y * Fn, P.x - this.x, P.y - this.y);
        // scrape friction
        const tlen = Math.hypot(1, n.slope);
        const tang = { x: 1 / tlen, y: n.slope / tlen };
        const vt = vp.x * tang.x + vp.y * tang.y;
        const ff = clamp(-vt * 1600, -Fn * 0.7, Fn * 0.7);
        this.applyForce(tang.x * ff, tang.y * ff, P.x - this.x, P.y - this.y);
        if (pen > 4) this.impact = Math.max(this.impact, Math.min(1, pen / 30));
      }
    }

    // winch cable
    if (this.winch.attached) {
      const wp = this.localToWorld(116, -14);
      const anchor = this.winch.anchor;
      let dx = anchor.x - wp.x;
      let dy = anchor.y - wp.y;
      const dist = Math.hypot(dx, dy) || 1;
      dx /= dist;
      dy /= dist;

      this.winch.ropeLen = Math.max(58, this.winch.ropeLen - this.winch.reelSpeed * dt);
      const stretch = dist - this.winch.ropeLen;
      if (stretch > -2) {
        const vp = this.velocityAt(116, -14);
        const vAlong = vp.x * dx + vp.y * dy;
        let force = clamp(stretch * 11500 - vAlong * 1400, 0, this.winch.forceMax);
        // the winch motor always pulls while taut
        force = Math.max(force, Math.min(this.winch.forceMax, 170000 + stretch * 2600));
        this.winch.force = force;
        this.winch.taut = true;
        this.applyForce(dx * force, dy * force, wp.x - this.x, wp.y - this.y);
      } else {
        this.winch.force = 0;
        this.winch.taut = false;
      }
      if (dist < 62 || dist > this.winch.maxRope * 1.35) this.detachWinch();
    }

    // angular damping
    this._torque -= this.av * this.inertia * (this.grounded ? 1.1 : 0.55);

    // integrate
    this.vx += (this._fx / this.mass) * dt;
    this.vy += (this._fy / this.mass) * dt;
    this.av += (this._torque / this.inertia) * dt;
    this.vx = clamp(this.vx, -1600, 1600);
    this.vy = clamp(this.vy, -1700, 1700);
    this.av = clamp(this.av, -7.5, 7.5);
    this.x += this.vx * dt;
    this.y += this.vy * dt;
    this.angle += this.av * dt;

    // keep the body from tunnelling through the ground on huge impacts
    if (this.y > t.heightAt(this.x) + 55) {
      this.y = t.heightAt(this.x) + 55;
      this.vy = Math.min(this.vy, 0);
    }

    this.impact *= 1 - dt * 5;
    this.winchCooldown = Math.max(0, this.winchCooldown - dt);
  }
}

// Tiny procedural sound engine: no external assets.
export class Sound {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.enabled = true;
    this.ready = false;
    this.lastThud = 0;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === "suspended") this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.enabled ? 0.55 : 0;
    this.master.connect(this.ctx.destination);

    // ---- engine ----
    this.engineGain = this.ctx.createGain();
    this.engineGain.gain.value = 0;
    this.engineFilter = this.ctx.createBiquadFilter();
    this.engineFilter.type = "lowpass";
    this.engineFilter.frequency.value = 420;
    this.engineFilter.Q.value = 3;
    this.engineGain.connect(this.engineFilter);
    this.engineFilter.connect(this.master);

    this.osc1 = this.ctx.createOscillator();
    this.osc1.type = "sawtooth";
    this.osc1.frequency.value = 42;
    this.osc2 = this.ctx.createOscillator();
    this.osc2.type = "square";
    this.osc2.frequency.value = 21;
    this.osc3 = this.ctx.createOscillator();
    this.osc3.type = "triangle";
    this.osc3.frequency.value = 84;
    const g1 = this.ctx.createGain(); g1.gain.value = 0.5;
    const g2 = this.ctx.createGain(); g2.gain.value = 0.32;
    const g3 = this.ctx.createGain(); g3.gain.value = 0.12;
    this.osc1.connect(g1); g1.connect(this.engineGain);
    this.osc2.connect(g2); g2.connect(this.engineGain);
    this.osc3.connect(g3); g3.connect(this.engineGain);
    this.osc1.start(); this.osc2.start(); this.osc3.start();

    // ---- noise buffer for mud / wind / impacts ----
    const len = this.ctx.sampleRate * 2;
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    this.noiseBuf = buf;

    this.mudGain = this.ctx.createGain();
    this.mudGain.gain.value = 0;
    this.mudFilter = this.ctx.createBiquadFilter();
    this.mudFilter.type = "bandpass";
    this.mudFilter.frequency.value = 620;
    this.mudFilter.Q.value = 0.8;
    const mudSrc = this.ctx.createBufferSource();
    mudSrc.buffer = buf;
    mudSrc.loop = true;
    mudSrc.connect(this.mudFilter);
    this.mudFilter.connect(this.mudGain);
    this.mudGain.connect(this.master);
    mudSrc.start();

    this.windGain = this.ctx.createGain();
    this.windGain.gain.value = 0;
    const windSrc = this.ctx.createBufferSource();
    windSrc.buffer = buf;
    windSrc.loop = true;
    const wf = this.ctx.createBiquadFilter();
    wf.type = "lowpass"; wf.frequency.value = 900;
    windSrc.connect(wf); wf.connect(this.windGain); this.windGain.connect(this.master);
    windSrc.start();

    this.winchGain = this.ctx.createGain();
    this.winchGain.gain.value = 0;
    this.winchOsc = this.ctx.createOscillator();
    this.winchOsc.type = "sawtooth";
    this.winchOsc.frequency.value = 74;
    const wf2 = this.ctx.createBiquadFilter();
    wf2.type = "lowpass"; wf2.frequency.value = 340;
    this.winchOsc.connect(wf2); wf2.connect(this.winchGain); this.winchGain.connect(this.master);
    this.winchOsc.start();

    this.ready = true;
  }

  setMuted(m) {
    this.enabled = !m;
    if (this.master) {
      this.master.gain.setTargetAtTime(this.enabled ? 0.55 : 0, this.ctx.currentTime, 0.03);
    }
  }

  update(state) {
    if (!this.ready) return;
    const now = this.ctx.currentTime;
    const { rpm = 0, throttle = 0, speed = 0, mud = 0, slip = 0, winch = 0, playing = true } = state;
    const idle = playing ? 1 : 0.35;
    const freq = 38 + rpm * 54 + Math.min(speed, 900) * 0.012;
    this.osc1.frequency.setTargetAtTime(freq, now, 0.08);
    this.osc2.frequency.setTargetAtTime(freq * 0.5, now, 0.08);
    this.osc3.frequency.setTargetAtTime(freq * 2.02, now, 0.08);
    this.engineFilter.frequency.setTargetAtTime(260 + throttle * 520 + rpm * 260, now, 0.09);
    const eg = playing ? (0.035 + throttle * 0.05 + rpm * 0.022) * idle : 0;
    this.engineGain.gain.setTargetAtTime(eg, now, 0.09);

    const mudLevel = playing ? Math.min(1, mud * 0.5 + slip / 420) * 0.16 : 0;
    this.mudGain.gain.setTargetAtTime(mudLevel, now, 0.06);
    this.mudFilter.frequency.setTargetAtTime(380 + Math.min(slip, 500) * 1.3, now, 0.08);

    this.windGain.gain.setTargetAtTime(playing ? Math.min(0.05, speed / 22000) : 0, now, 0.2);
    this.winchGain.gain.setTargetAtTime(playing ? Math.min(0.055, winch * 0.00000006) : 0, now, 0.08);
    this.winchOsc.frequency.setTargetAtTime(64 + Math.min(winch / 20000, 28), now, 0.12);
  }

  blip(freq = 900, dur = 0.12, type = "sine", vol = 0.1, slide = 1.5) {
    if (!this.ready || !this.enabled) return;
    const now = this.ctx.currentTime;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(freq, now);
    o.frequency.exponentialRampToValueAtTime(freq * slide, now + dur);
    g.gain.setValueAtTime(vol, now);
    g.gain.exponentialRampToValueAtTime(0.0001, now + dur);
    o.connect(g); g.connect(this.master);
    o.start(now); o.stop(now + dur + 0.02);
  }

  coin() {
    this.blip(960, 0.09, "sine", 0.1, 1.55);
    setTimeout(() => this.blip(1440, 0.13, "sine", 0.07, 1.2), 55);
  }

  buy() {
    this.blip(300, 0.1, "square", 0.06, 1.4);
    setTimeout(() => this.blip(520, 0.16, "square", 0.05, 1.25), 70);
  }

  click() {
    this.blip(520, 0.04, "square", 0.025, 0.7);
  }

  thud(power = 1) {
    if (!this.ready || !this.enabled) return;
    const now = this.ctx.currentTime;
    if (now - this.lastThud < 0.09) return;
    this.lastThud = now;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuf;
    const f = this.ctx.createBiquadFilter();
    f.type = "lowpass"; f.frequency.value = 160;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(Math.min(0.22, 0.07 * power), now);
    g.gain.exponentialRampToValueAtTime(0.0001, now + 0.22);
    src.connect(f); f.connect(g); g.connect(this.master);
    src.start(now); src.stop(now + 0.24);
  }

  splash(power = 1) {
    if (!this.ready || !this.enabled) return;
    const now = this.ctx.currentTime;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuf;
    const f = this.ctx.createBiquadFilter();
    f.type = "bandpass"; f.frequency.value = 480;
    f.Q.value = 1.4;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(Math.min(0.16, 0.06 * power), now);
    g.gain.exponentialRampToValueAtTime(0.0001, now + 0.3);
    src.connect(f); f.connect(g); g.connect(this.master);
    src.start(now); src.stop(now + 0.32);
  }

  winchAttach() {
    this.blip(170, 0.16, "sawtooth", 0.05, 1.9);
    setTimeout(() => this.blip(340, 0.08, "square", 0.035, 0.8), 120);
  }
}

// Canvas renderer: layered landscape, detailed UAZ, particles and camera.
import { clamp, lerp, PX_PER_M, STEP, START_X } from "./terrain.js";

const TAU = Math.PI * 2;
const hash = (n) => {
  const x = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return x - Math.floor(x);
};

export class Renderer {
  constructor(canvas, terrain) {
    this.canvas = canvas;
    this.ctx = canvas.getContext("2d");
    this.terrain = terrain;
    this.W = 1280;
    this.H = 720;
    this.dpr = 1;
    this.baseZoom = 1;
    this.zoom = 1;
    this.cam = { x: START_X, y: terrain.heightAt(START_X) - 100 };
    this.targetZoom = 1;
    this.time = 0;
    this.shake = 0;
    this.shakeX = 0;
    this.shakeY = 0;
    this.particles = [];
    this.exhaustTimer = 0;
    this.anchorHint = null;
    this.winchPulse = 0;
    this.clouds = [];
    for (let i = 0; i < 12; i++) {
      this.clouds.push({
        x: hash(i * 3.1) * 2400,
        y: 40 + hash(i * 7.7) * 190,
        s: 0.5 + hash(i * 11.3) * 1.1,
        a: 0.1 + hash(i * 5.5) * 0.18,
      });
    }
    this.resize();
  }

  resize() {
    const W = window.innerWidth;
    const H = window.innerHeight;
    this.dpr = Math.min(2, window.devicePixelRatio || 1);
    this.W = W;
    this.H = H;
    this.canvas.width = Math.round(W * this.dpr);
    this.canvas.height = Math.round(H * this.dpr);
    this.canvas.style.width = W + "px";
    this.canvas.style.height = H + "px";
    this.baseZoom = clamp(Math.min(W / 1280, H / 760), 0.58, 1.18);
    this.zoom = this.baseZoom;
    this.targetZoom = this.baseZoom;
  }

  snapCamera(truck) {
    this.cam.x = truck.x + 30;
    this.cam.y = truck.y - 10;
    this.zoom = this.baseZoom;
    this.targetZoom = this.baseZoom;
  }

  updateCamera(truck, dt, snap = false) {
    const speed = Math.hypot(truck.vx, truck.vy);
    const tx = truck.x + clamp(truck.vx * 0.3, -150, 230) + 36;
    const ty = truck.y - 16 + clamp(truck.vy * 0.1, -70, 90);
    const k = snap ? 1 : 1 - Math.exp(-dt * 3.4);
    const ky = snap ? 1 : 1 - Math.exp(-dt * 2.6);
    this.cam.x += (tx - this.cam.x) * k;
    this.cam.y += (ty - this.cam.y) * ky;
    this.targetZoom = this.baseZoom * (1 - Math.min(0.1, speed / 11000));
    this.zoom += (this.targetZoom - this.zoom) * (snap ? 1 : 1 - Math.exp(-dt * 2));
  }

  addShake(amount) {
    this.shake = Math.min(1.4, this.shake + amount);
  }

  spawnParticle(p) {
    if (this.particles.length > 460) this.particles.shift();
    this.particles.push(p);
  }

  spawnMud(x, y, vx, vy, size = 3, life = 0.8) {
    this.spawnParticle({
      x, y, vx, vy,
      g: 950,
      life,
      maxLife: life,
      size,
      type: "mud",
      rot: Math.random() * TAU,
      vr: (Math.random() - 0.5) * 10,
    });
  }

  spawnDust(x, y, vx, vy, size = 4) {
    this.spawnParticle({
      x, y, vx, vy, g: 80, life: 0.9 + Math.random() * 0.7,
      maxLife: 1.6, size, type: "dust", grow: 9,
    });
  }

  spawnSmoke(x, y, vx, vy) {
    this.spawnParticle({
      x, y, vx, vy, g: -22, life: 0.9 + Math.random() * 0.5,
      maxLife: 1.4, size: 3 + Math.random() * 3, type: "smoke", grow: 12,
    });
  }

  spawnSpark(x, y, vx, vy) {
    this.spawnParticle({
      x, y, vx, vy, g: 500, life: 0.45 + Math.random() * 0.3,
      maxLife: 0.75, size: 1.5 + Math.random() * 1.8, type: "spark",
    });
  }

  coinBurst(x, y) {
    for (let i = 0; i < 9; i++) {
      const a = (i / 9) * TAU + Math.random() * 0.4;
      const sp = 60 + Math.random() * 120;
      this.spawnParticle({
        x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 60,
        g: 260, life: 0.5 + Math.random() * 0.4, maxLife: 0.9,
        size: 2 + Math.random() * 2.4, type: "spark",
      });
    }
  }

  splashBurst(x, y, power = 1) {
    for (let i = 0; i < 16; i++) {
      const a = -Math.PI * 0.15 - Math.random() * Math.PI * 0.7;
      const sp = (60 + Math.random() * 210) * power;
      this.spawnMud(
        x + (Math.random() - 0.5) * 30,
        y,
        Math.cos(a) * sp,
        Math.sin(a) * sp,
        2 + Math.random() * 4,
        0.6 + Math.random() * 0.7
      );
    }
  }

  updateParticles(dt, game) {
    const truck = game.truck;
    const playing = game.state === "playing";
    this.time += dt;
    this.winchPulse += dt;
    if (this.shake > 0) {
      this.shake = Math.max(0, this.shake - dt * 2.6);
      this.shakeX = (Math.random() - 0.5) * this.shake * 13;
      this.shakeY = (Math.random() - 0.5) * this.shake * 10;
    } else {
      this.shakeX = 0;
      this.shakeY = 0;
    }

    if (playing) {
      // exhaust
      this.exhaustTimer -= dt;
      const throttle = truck.input.gas || 0;
      if (this.exhaustTimer <= 0 && (throttle > 0 || Math.abs(truck.forwardSpeed()) > 80)) {
        this.exhaustTimer = 0.06 + Math.random() * 0.06;
        const p = truck.localToWorld(-126, 34);
        const f = truck.localToWorld(-100, 34);
        this.spawnSmoke(
          p.x, p.y,
          (p.x - f.x) * 1.1 + (Math.random() - 0.5) * 18,
          (p.y - f.y) * 1.1 - 10 - Math.random() * 14
        );
      }

      // wheel spray & dust
      for (const w of truck.wheels) {
        if (!w.contact) {
          w._spray = 0;
          continue;
        }
        const speed = Math.abs(w.slip);
        if (w.softness > 0.14 && speed > 35) {
          w._spray = (w._spray || 0) + dt * (6 + speed * 0.13);
          while (w._spray > 1) {
            w._spray -= 1;
            const back = -Math.sign(w.slip || 1);
            this.spawnMud(
              w.contactX + (Math.random() - 0.5) * 20,
              w.contactY - 2,
              w.tangent.x * back * (60 + Math.random() * 210) + (Math.random() - 0.5) * 40,
              -40 - Math.random() * 190,
              1.8 + Math.random() * 4,
              0.5 + Math.random() * 0.8
            );
          }
        } else if (w.softness < 0.2 && truck.speed > 120) {
          w._spray = (w._spray || 0) + dt * 2.2;
          while (w._spray > 1) {
            w._spray -= 1;
            this.spawnDust(
              w.contactX + (Math.random() - 0.5) * 24,
              w.contactY - 2,
              -Math.sign(truck.vx || 1) * (20 + Math.random() * 50),
              -10 - Math.random() * 30,
              2 + Math.random() * 4
            );
          }
        }
      }
    }

    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.life -= dt;
      if (p.life <= 0) {
        this.particles.splice(i, 1);
        continue;
      }
      p.vy += (p.g || 0) * dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      if (p.type === "mud" || p.type === "spark") {
        p.vx *= 1 - dt * 1.4;
      } else if (p.type === "dust" || p.type === "smoke") {
        p.vx *= 1 - dt * 1.1;
        p.vy *= 1 - dt * 0.8;
        p.size += (p.grow || 0) * dt;
      }
      if (p.rot !== undefined) p.rot += (p.vr || 0) * dt;
    }
  }

  // ---------------- drawing ----------------
  render(game) {
    const ctx = this.ctx;
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    ctx.clearRect(0, 0, this.W, this.H);
    this.drawSky(game);
    this.drawParallax(game);

    ctx.save();
    ctx.translate(this.W / 2 + this.shakeX, this.H / 2 + this.shakeY);
    ctx.scale(this.zoom, this.zoom);
    ctx.translate(-this.cam.x, -this.cam.y);

    this.drawTerrain();
    this.drawWorldDecor(game);
    this.drawCoins(game);
    this.drawWinchHint(game);
    this.drawTruck(game.truck);
    this.drawParticles();
    this.drawWinchCable(game.truck);
    ctx.restore();

    this.drawScreenOverlays(game);
  }

  drawSky(game) {
    const ctx = this.ctx;
    const W = this.W;
    const H = this.H;
    const g = ctx.createLinearGradient(0, 0, 0, H * 0.72);
    g.addColorStop(0, "#5d7f91");
    g.addColorStop(0.34, "#8fa5a2");
    g.addColorStop(0.62, "#cbbd9a");
    g.addColorStop(0.85, "#e6c996");
    g.addColorStop(1, "#e9c48e");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, W, H);

    // sun
    const sx = W * 0.77;
    const sy = H * 0.18 - (this.cam.y - 450) * 0.035;
    const sun = ctx.createRadialGradient(sx, sy, 4, sx, sy, 160);
    sun.addColorStop(0, "rgba(255, 243, 204, 0.95)");
    sun.addColorStop(0.12, "rgba(255, 227, 158, 0.7)");
    sun.addColorStop(0.45, "rgba(255, 210, 130, 0.16)");
    sun.addColorStop(1, "rgba(255, 200, 120, 0)");
    ctx.fillStyle = sun;
    ctx.fillRect(sx - 180, sy - 180, 360, 360);
    ctx.beginPath();
    ctx.arc(sx, sy, 25, 0, TAU);
    ctx.fillStyle = "rgba(255, 246, 215, 0.85)";
    ctx.fill();

    // clouds
    const drift = this.time * 3 + this.cam.x * 0.012;
    for (const c of this.clouds) {
      let x = ((c.x - drift) % 2400 + 2400) % 2400 - 400;
      const y = c.y + Math.sin(c.x) * 16 - (this.cam.y - 450) * 0.025;
      if (x < -400 || x > W + 400) continue;
      ctx.save();
      ctx.globalAlpha = c.a;
      ctx.fillStyle = "#f3e7cc";
      ctx.beginPath();
      ctx.ellipse(x, y, 90 * c.s, 16 * c.s, 0, 0, TAU);
      ctx.ellipse(x + 44 * c.s, y - 8 * c.s, 58 * c.s, 14 * c.s, 0, 0, TAU);
      ctx.ellipse(x - 48 * c.s, y + 2 * c.s, 52 * c.s, 11 * c.s, 0, 0, TAU);
      ctx.fill();
      ctx.restore();
    }
  }

  drawParallax() {
    const ctx = this.ctx;
    const W = this.W;
    const H = this.H;
    const camX = this.cam.x;
    const camY = this.cam.y;
    const horizon = H * 0.66 - (camY - 450) * 0.05;

    const layers = [
      { f: 0.06, amp: 92, base: horizon - 42, color: "#8b9a8c", step: 0.0035, ph: 1.2 },
      { f: 0.11, amp: 126, base: horizon + 6, color: "#73846f", step: 0.0027, ph: 4.1 },
      { f: 0.19, amp: 158, base: horizon + 58, color: "#596b56", step: 0.0021, ph: 2.2 },
      { f: 0.31, amp: 130, base: horizon + 112, color: "#44543f", step: 0.0031, ph: 5.4 },
    ];
    for (const L of layers) {
      ctx.beginPath();
      ctx.moveTo(-80, H + 10);
      for (let x = -80; x <= W + 80; x += 18) {
        const wx = x + camX * L.f;
        const y =
          L.base +
          Math.sin(wx * L.step + L.ph) * L.amp +
          Math.sin(wx * L.step * 2.7 + L.ph * 1.7) * L.amp * 0.34 +
          Math.sin(wx * L.step * 0.37 + 2) * L.amp * 0.5;
        ctx.lineTo(x, y);
      }
      ctx.lineTo(W + 80, H + 10);
      ctx.closePath();
      ctx.fillStyle = L.color;
      ctx.fill();
    }

    // haze at the tree line
    const haze = ctx.createLinearGradient(0, horizon + 10, 0, horizon + 190);
    haze.addColorStop(0, "rgba(231, 208, 168, 0.34)");
    haze.addColorStop(1, "rgba(231, 208, 168, 0)");
    ctx.fillStyle = haze;
    ctx.fillRect(0, horizon + 10, W, 190);

    // distant tree line
    ctx.fillStyle = "rgba(45, 58, 42, 0.62)";
    for (let i = 0; i < 90; i++) {
      const wx = i * 47 + camX * 0.26;
      const x = ((wx % (W + 200)) + W + 200) % (W + 200) - 100;
      const h = 16 + hash(i * 4.7) * 36;
      const baseY = horizon + 72 + Math.sin(i * 0.8) * 10;
      ctx.beginPath();
      ctx.moveTo(x, baseY);
      ctx.lineTo(x + 6, baseY - h);
      ctx.lineTo(x + 12, baseY);
      ctx.fill();
    }

    // birds
    ctx.strokeStyle = "rgba(36, 42, 34, 0.55)";
    ctx.lineWidth = 1.4;
    for (let i = 0; i < 4; i++) {
      const bx = ((this.time * (6 + i * 2) + i * 240 - camX * 0.02) % (W + 200)) - 100;
      const by = H * 0.16 + i * 26 + Math.sin(this.time * 0.8 + i) * 8;
      ctx.beginPath();
      ctx.moveTo(bx - 6, by);
      ctx.quadraticCurveTo(bx - 2, by - 4, bx, by);
      ctx.quadraticCurveTo(bx + 2, by - 4, bx + 6, by);
      ctx.stroke();
    }
  }

  drawTerrain() {
    const ctx = this.ctx;
    const t = this.terrain;
    const left = this.cam.x - this.W / (2 * this.zoom) - 80;
    const right = this.cam.x + this.W / (2 * this.zoom) + 80;
    const bottom = this.cam.y + this.H / (2 * this.zoom) + 200;
    let i0 = Math.floor(left / STEP);
    let i1 = Math.ceil(right / STEP);
    i0 = clamp(i0, 1, t.count - 2);
    i1 = clamp(i1, i0 + 2, t.count - 2);

    // terrain body
    ctx.beginPath();
    ctx.moveTo(i0 * STEP, bottom + 40);
    for (let i = i0; i <= i1; i += 2) {
      ctx.lineTo(i * STEP, t.heights[i]);
    }
    ctx.lineTo(i1 * STEP, bottom + 40);
    ctx.closePath();

    const topY = Math.min(t.heights[i0], t.heights[i1]) - 80;
    const g = ctx.createLinearGradient(0, topY, 0, bottom);
    g.addColorStop(0, "#4b3a28");
    g.addColorStop(0.25, "#3a2d20");
    g.addColorStop(0.65, "#2b2118");
    g.addColorStop(1, "#1b1611");
    ctx.fillStyle = g;
    ctx.fill();

    ctx.save();
    ctx.clip();

    // strata
    for (let s = 0; s < 4; s++) {
      const depth = 62 + s * 88;
      ctx.beginPath();
      for (let i = i0; i <= i1; i += 4) {
        const x = i * STEP;
        const y = t.heights[i] + depth + Math.sin(x * 0.008 + s * 2.4) * (8 + s * 3);
        if (i === i0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.strokeStyle = s % 2 ? "rgba(255, 232, 195, 0.045)" : "rgba(0, 0, 0, 0.16)";
      ctx.lineWidth = 2 + s * 0.6;
      ctx.stroke();
    }

    // embedded stones
    for (let x = Math.floor(left / 90) * 90; x < right; x += 90) {
      const h = hash(x * 0.031);
      if (h < 0.42) continue;
      const gy = t.heightAt(x) + 34 + hash(x * 0.017) * 190;
      const s = 2 + hash(x * 0.071) * 7;
      ctx.beginPath();
      ctx.ellipse(x + h * 22, gy, s * 1.4, s, h * 2, 0, TAU);
      ctx.fillStyle = h > 0.75 ? "rgba(120, 105, 80, 0.22)" : "rgba(10, 8, 6, 0.25)";
      ctx.fill();
    }

    // topsoil band
    ctx.beginPath();
    for (let i = i0; i <= i1; i += 2) {
      const x = i * STEP;
      const y = t.heights[i];
      if (i === i0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.strokeStyle = "#5a432c";
    ctx.lineWidth = 20;
    ctx.lineJoin = "round";
    ctx.stroke();
    ctx.strokeStyle = "#4a3624";
    ctx.lineWidth = 10;
    ctx.stroke();

    // wet mud pools
    for (const pit of t.mudPits) {
      if (pit.x < left - pit.w || pit.x > right + pit.w) continue;
      const gy = t.heightAt(pit.x);
      const pg = ctx.createLinearGradient(0, gy - 10, 0, gy + 24);
      pg.addColorStop(0, "rgba(28, 21, 15, 0.75)");
      pg.addColorStop(1, "rgba(22, 17, 12, 0.2)");
      ctx.fillStyle = pg;
      ctx.beginPath();
      ctx.ellipse(pit.x, gy + 3, pit.w * 0.48, 11, 0, 0, TAU);
      ctx.fill();
      ctx.strokeStyle = "rgba(210, 190, 150, 0.14)";
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.ellipse(pit.x - pit.w * 0.08, gy - 1, pit.w * 0.3, 4, 0, 0, TAU);
      ctx.stroke();
    }

    // disturbed / rutted ground
    ctx.lineCap = "round";
    for (let i = i0; i < i1; i += 2) {
      const x = i * STEP;
      const d = t.disturb[i];
      if (d < 0.16) continue;
      const y = t.heights[i];
      ctx.beginPath();
      ctx.moveTo(x, y - 1);
      ctx.lineTo((i + 2) * STEP, t.heights[Math.min(t.count - 1, i + 2)] - 1);
      ctx.strokeStyle = `rgba(32, 23, 15, ${Math.min(0.65, 0.18 + d * 0.45)})`;
      ctx.lineWidth = 9 + Math.min(8, d * 8);
      ctx.stroke();
    }

    ctx.restore();

    // surface line (grass / dirt / mud)
    ctx.lineCap = "round";
    for (let i = i0; i < i1; i += 2) {
      const x = i * STEP;
      const nx = (i + 2) * STEP;
      const s = Math.max(t.softness[i], t.softness[Math.min(t.count - 1, i + 2)]);
      const d = Math.max(t.disturb[i], t.disturb[Math.min(t.count - 1, i + 2)]);
      const y = t.heights[i];
      const ny = t.heights[Math.min(t.count - 1, i + 2)];
      let color = "#7c8c49";
      let width = 4.5;
      if (d > 0.3 || s > 0.62) {
        color = "#3a2a1c";
        width = 9;
      } else if (s > 0.28) {
        color = "#5d452c";
        width = 7;
      } else if (s > 0.12) {
        color = "#6b6236";
        width = 5.5;
      }
      ctx.strokeStyle = color;
      ctx.lineWidth = width;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(nx, ny);
      ctx.stroke();
      if (s < 0.2) {
        ctx.strokeStyle = "rgba(171, 186, 104, 0.5)";
        ctx.lineWidth = 1.6;
        ctx.beginPath();
        ctx.moveTo(x, y - 1);
        ctx.lineTo(nx, ny - 1);
        ctx.stroke();
      }
    }

    // grass tufts
    for (let x = Math.floor(left / 26) * 26; x < right; x += 26) {
      const s = t.softnessAt(x);
      if (s > 0.28) continue;
      const h = hash(x * 0.13);
      if (h < 0.28) continue;
      const gy = t.heightAt(x);
      const n = 2 + Math.floor(h * 3);
      ctx.strokeStyle = h > 0.7 ? "rgba(147, 163, 87, 0.8)" : "rgba(103, 121, 62, 0.85)";
      ctx.lineWidth = 1.4;
      for (let k = 0; k < n; k++) {
        const bx = x + (k - n / 2) * 3;
        ctx.beginPath();
        ctx.moveTo(bx, gy);
        ctx.quadraticCurveTo(
          bx + (hash(x + k * 9) - 0.5) * 8,
          gy - 7 - h * 8,
          bx + (hash(x + k * 13) - 0.5) * 13,
          gy - 11 - h * 12
        );
        ctx.stroke();
      }
      if (h > 0.82) {
        ctx.fillStyle = "rgba(220, 192, 105, 0.85)";
        ctx.beginPath();
        ctx.arc(x + 4, gy - 12 - h * 8, 1.8, 0, TAU);
        ctx.fill();
      }
    }
  }

  drawWorldDecor(game) {
    const t = this.terrain;
    const left = this.cam.x - this.W / (2 * this.zoom) - 160;
    const right = this.cam.x + this.W / (2 * this.zoom) + 160;

    // trees
    for (const tree of t.trees) {
      if (tree.x < left || tree.x > right) continue;
      this.drawTree(tree);
    }
    // bushes
    for (const b of t.bushes) {
      if (b.x < left || b.x > right) continue;
      this.drawBush(b);
    }
    // rocks
    for (const r of t.rocks) {
      if (r.x < left || r.x > right) continue;
      this.drawRock(r);
    }

    // distance flags
    const flagSpacing = 100 * PX_PER_M;
    const startFlag = Math.floor((left - START_X) / flagSpacing) * flagSpacing + START_X;
    for (let x = startFlag; x < right; x += flagSpacing) {
      if (x < START_X + 200) continue;
      const m = Math.round((x - START_X) / PX_PER_M);
      if (m <= 0) continue;
      this.drawDistanceFlag(x, m);
    }

    // mud warning stakes
    for (const pit of t.mudPits) {
      if (pit.x < left - pit.w || pit.x > right + pit.w) continue;
      this.drawMudStake(pit.x - pit.w * 0.56);
      this.drawMudStake(pit.x + pit.w * 0.56);
    }

    void game;
  }

  drawTree(tree) {
    const ctx = this.ctx;
    const sway = Math.sin(this.time * 0.55 + tree.seed) * 0.018;
    const scale = tree.h / 130;
    ctx.save();
    ctx.translate(tree.x, tree.y + 2);
    ctx.rotate(tree.lean + sway);
    ctx.fillStyle = "rgba(0, 0, 0, 0.18)";
    ctx.beginPath();
    ctx.ellipse(0, 2, 24 * scale, 5 * scale, 0, 0, TAU);
    ctx.fill();

    if (tree.type === "pine") {
      ctx.fillStyle = "#3c2f21";
      ctx.fillRect(-2.5 * scale, -tree.h * 0.55, 5 * scale, tree.h * 0.58);
      const layers = 3;
      for (let i = 0; i < layers; i++) {
        const y = -tree.h * (0.25 + i * 0.22);
        const w = (30 - i * 6) * scale;
        const h = (44 - i * 5) * scale;
        ctx.fillStyle = i === 0 ? "#2f4128" : i === 1 ? "#394d2d" : "#455b33";
        ctx.beginPath();
        ctx.moveTo(-w, y + h * 0.35);
        ctx.lineTo(0, y - h * 0.7);
        ctx.lineTo(w, y + h * 0.35);
        ctx.closePath();
        ctx.fill();
      }
      ctx.fillStyle = "rgba(120, 143, 80, 0.25)";
      ctx.beginPath();
      ctx.moveTo(-12 * scale, -tree.h * 0.6);
      ctx.lineTo(0, -tree.h * 0.88);
      ctx.lineTo(6 * scale, -tree.h * 0.6);
      ctx.closePath();
      ctx.fill();
    } else if (tree.type === "birch") {
      ctx.strokeStyle = "#cbc5ab";
      ctx.lineWidth = 4.4 * scale;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(4 * scale, -tree.h * 0.4, 2 * scale, -tree.h * 0.78);
      ctx.stroke();
      ctx.strokeStyle = "rgba(48, 45, 35, 0.7)";
      ctx.lineWidth = 1.4 * scale;
      for (let i = 0; i < 7; i++) {
        const yy = -tree.h * (0.12 + i * 0.09);
        ctx.beginPath();
        ctx.moveTo(-3 * scale, yy);
        ctx.lineTo(3.4 * scale, yy - 1.5);
        ctx.stroke();
      }
      const blobs = [
        [0, -0.8, 23], [15, -0.68, 16], [-15, -0.7, 18],
        [7, -0.9, 14], [-8, -0.88, 13],
      ];
      for (const [bx, by, br] of blobs) {
        ctx.fillStyle = hash(tree.seed + bx) > 0.5 ? "#64783e" : "#748846";
        ctx.beginPath();
        ctx.arc(bx * scale, by * tree.h, br * scale, 0, TAU);
        ctx.fill();
      }
    } else {
      ctx.strokeStyle = "#5b5344";
      ctx.lineWidth = 4 * scale;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(-4 * scale, -tree.h * 0.35, 3 * scale, -tree.h * 0.66);
      ctx.stroke();
      ctx.lineWidth = 2 * scale;
      for (let i = 0; i < 4; i++) {
        const y = -tree.h * (0.3 + i * 0.11);
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo((i % 2 ? 1 : -1) * (12 + i * 3) * scale, y - 14 * scale);
        ctx.stroke();
      }
    }
    ctx.restore();
  }

  drawBush(b) {
    const ctx = this.ctx;
    ctx.save();
    ctx.translate(b.x, b.y);
    ctx.fillStyle = "rgba(0,0,0,0.14)";
    ctx.beginPath();
    ctx.ellipse(0, 1, 16 * b.s, 4 * b.s, 0, 0, TAU);
    ctx.fill();
    const n = 4;
    for (let i = 0; i < n; i++) {
      const a = (i / n) * TAU;
      ctx.fillStyle = i % 2 ? "#4b5c31" : "#5a6b38";
      ctx.beginPath();
      ctx.arc(Math.cos(a) * 7 * b.s, -8 * b.s + Math.sin(a) * 4 * b.s, (8 + hash(b.seed + i) * 4) * b.s, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
  }

  drawRock(r) {
    const ctx = this.ctx;
    ctx.save();
    ctx.translate(r.x, r.y);
    ctx.rotate(r.rot);
    ctx.fillStyle = "#5d5b4f";
    ctx.beginPath();
    ctx.moveTo(-r.s, 1);
    ctx.lineTo(-r.s * 0.5, -r.s * 0.75);
    ctx.lineTo(r.s * 0.35, -r.s * 0.9);
    ctx.lineTo(r.s, -r.s * 0.1);
    ctx.lineTo(r.s * 0.55, r.s * 0.3);
    ctx.lineTo(-r.s * 0.7, r.s * 0.3);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = "rgba(255,255,255,0.12)";
    ctx.beginPath();
    ctx.moveTo(-r.s * 0.5, -r.s * 0.7);
    ctx.lineTo(r.s * 0.3, -r.s * 0.82);
    ctx.lineTo(r.s * 0.1, -r.s * 0.3);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  drawDistanceFlag(x, m) {
    const ctx = this.ctx;
    const y = this.terrain.heightAt(x);
    const sector = m % 250 === 0;
    const h = sector ? 76 : 52;
    ctx.save();
    ctx.translate(x, y);
    ctx.strokeStyle = "#4c4536";
    ctx.lineWidth = 2.4;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(0, -h);
    ctx.stroke();
    ctx.fillStyle = sector ? "#d9a63a" : "#8da150";
    ctx.beginPath();
    ctx.moveTo(0, -h + 2);
    ctx.lineTo(sector ? 42 : 30, -h + (sector ? 13 : 9));
    ctx.lineTo(0, -h + (sector ? 26 : 18));
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = "rgba(24, 26, 18, 0.8)";
    ctx.font = `700 ${sector ? 10 : 8}px Arial Narrow, Arial`;
    ctx.textAlign = "center";
    ctx.fillText(`${m}m`, sector ? 17 : 12, -h + (sector ? 16 : 12));
    ctx.restore();
  }

  drawMudStake(x) {
    const ctx = this.ctx;
    const y = this.terrain.heightAt(x);
    ctx.save();
    ctx.translate(x, y);
    ctx.strokeStyle = "#6a5334";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(0, -26);
    ctx.stroke();
    ctx.fillStyle = "#d6c9a2";
    ctx.fillRect(-5, -30, 10, 7);
    ctx.fillStyle = "#b4603b";
    ctx.fillRect(-5, -26, 10, 3);
    ctx.restore();
  }

  drawCoins(game) {
    const ctx = this.ctx;
    const t = this.time;
    const left = this.cam.x - this.W / (2 * this.zoom) - 80;
    const right = this.cam.x + this.W / (2 * this.zoom) + 80;
    for (const c of game.coins) {
      if (c.taken || c.x < left || c.x > right) continue;
      const bob = Math.sin(t * 2.6 + c.seed) * 4;
      const spin = Math.abs(Math.cos(t * 2.2 + c.seed));
      const sx = 0.3 + spin * 0.7;
      const y = c.y + bob;
      const glow = ctx.createRadialGradient(c.x, y, 2, c.x, y, 26);
      glow.addColorStop(0, "rgba(255, 210, 110, 0.34)");
      glow.addColorStop(1, "rgba(255, 210, 110, 0)");
      ctx.fillStyle = glow;
      ctx.beginPath();
      ctx.arc(c.x, y, 26, 0, TAU);
      ctx.fill();
      ctx.save();
      ctx.translate(c.x, y);
      ctx.scale(sx, 1);
      ctx.beginPath();
      ctx.arc(0, 0, 11, 0, TAU);
      ctx.fillStyle = "#d7a432";
      ctx.fill();
      ctx.lineWidth = 2;
      ctx.strokeStyle = "#f8dd8c";
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(0, 0, 6.4, 0, TAU);
      ctx.strokeStyle = "rgba(122, 82, 17, 0.75)";
      ctx.lineWidth = 1.2;
      ctx.stroke();
      ctx.fillStyle = "rgba(255, 245, 205, 0.9)";
      ctx.font = "700 8px Arial";
      ctx.textAlign = "center";
      ctx.fillText("₽", 0, 3);
      ctx.restore();
    }
  }

  drawWinchHint(game) {
    if (!this.anchorHint || game.truck.winch.attached) return;
    const ctx = this.ctx;
    const p = this.anchorHint;
    const pulse = (Math.sin(this.winchPulse * 3) + 1) * 0.5;
    ctx.save();
    ctx.strokeStyle = `rgba(157, 180, 91, ${0.28 + pulse * 0.4})`;
    ctx.lineWidth = 1.6;
    ctx.setLineDash([4, 5]);
    ctx.beginPath();
    ctx.arc(p.x, p.y - 26, 18 + pulse * 5, 0, TAU);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = `rgba(157, 180, 91, ${0.55 + pulse * 0.35})`;
    ctx.beginPath();
    ctx.moveTo(p.x, p.y - 52 - pulse * 4);
    ctx.lineTo(p.x - 5, p.y - 60 - pulse * 4);
    ctx.lineTo(p.x + 5, p.y - 60 - pulse * 4);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  drawTruck(truck) {
    const ctx = this.ctx;
    const t = this.terrain;
    const cos = Math.cos(truck.angle);
    const sin = Math.sin(truck.angle);
    const r = truck.radius;

    // ground shadow
    const gy = t.heightAt(truck.x);
    const air = clamp(1 - (gy - truck.y) / 300, 0.25, 1);
    ctx.save();
    ctx.translate(truck.x, gy + 3);
    ctx.fillStyle = `rgba(8, 7, 5, ${0.26 * air})`;
    ctx.beginPath();
    ctx.ellipse(0, 0, 126 * (0.8 + air * 0.2), 9, 0, 0, TAU);
    ctx.fill();
    ctx.restore();

    // suspension arms + springs
    const wheelLocal = truck.wheels.map((w) => {
      const dx = w.cx - truck.x;
      const dy = w.cy - truck.y;
      return { x: dx * cos + dy * sin, y: -dx * sin + dy * cos, w };
    });

    ctx.save();
    ctx.translate(truck.x, truck.y);
    ctx.rotate(truck.angle);

    for (const wl of wheelLocal) {
      const ax = wl.w.ax;
      const ay = wl.w.ay;
      ctx.strokeStyle = "#22251d";
      ctx.lineWidth = 5;
      ctx.beginPath();
      ctx.moveTo(ax * 0.45, ay + 2);
      ctx.lineTo(wl.x, wl.y);
      ctx.stroke();
      ctx.strokeStyle = "#3a3e31";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(ax, ay);
      ctx.lineTo(wl.x, wl.y);
      ctx.stroke();
      // coil spring
      const dx = wl.x - ax;
      const dy = wl.y - ay;
      const len = Math.hypot(dx, dy) || 1;
      const nx = -dy / len;
      const ny = dx / len;
      ctx.strokeStyle = "#8b8b6e";
      ctx.lineWidth = 1.4;
      ctx.beginPath();
      const coils = 7;
      for (let i = 0; i <= coils; i++) {
        const f = i / coils;
        const off = (i % 2 ? 1 : -1) * 3;
        const px = ax + dx * f + nx * off;
        const py = ay + dy * f + ny * off;
        if (i === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      }
      ctx.stroke();
    }

    // wheels
    for (const wl of wheelLocal) this.drawWheel(wl.x, wl.y, r, wl.w, truck);

    this.drawBody(truck, r);

    // fender flares
    for (const wl of wheelLocal) {
      ctx.save();
      ctx.translate(wl.x, wl.y);
      ctx.strokeStyle = "#252a1d";
      ctx.lineWidth = 9;
      ctx.beginPath();
      ctx.arc(0, 0, r + 5, Math.PI * 1.02, Math.PI * 1.98);
      ctx.stroke();
      ctx.strokeStyle = "#4d5735";
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.arc(0, 0, r + 5, Math.PI * 1.04, Math.PI * 1.96);
      ctx.stroke();
      ctx.restore();
    }

    ctx.restore();
  }

  drawWheel(x, y, r, w, truck) {
    const ctx = this.ctx;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(w.spin);

    // tire
    ctx.beginPath();
    ctx.arc(0, 0, r, 0, TAU);
    ctx.fillStyle = "#1c1b17";
    ctx.fill();
    ctx.lineWidth = 3;
    ctx.strokeStyle = "#0f0f0c";
    ctx.stroke();

    // tread blocks
    const blocks = 13;
    for (let i = 0; i < blocks; i++) {
      const a = (i / blocks) * TAU;
      ctx.save();
      ctx.rotate(a);
      ctx.fillStyle = i % 2 ? "#24221c" : "#2c2922";
      ctx.fillRect(r - 5, -r * 0.135, 4.5, r * 0.27);
      ctx.fillStyle = "rgba(255,255,255,0.035)";
      ctx.fillRect(r - 5, -r * 0.135, 1.5, r * 0.27);
      ctx.restore();
    }

    // sidewall
    ctx.beginPath();
    ctx.arc(0, 0, r * 0.8, 0, TAU);
    ctx.strokeStyle = "#302d26";
    ctx.lineWidth = 2;
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(0, 0, r * 0.62, 0, TAU);
    ctx.fillStyle = "#65614d";
    ctx.fill();
    ctx.strokeStyle = "#8e886b";
    ctx.lineWidth = 1.4;
    ctx.stroke();

    // steel rim + lugs
    for (let i = 0; i < 6; i++) {
      const a = (i / 6) * TAU;
      ctx.beginPath();
      ctx.arc(Math.cos(a) * r * 0.36, Math.sin(a) * r * 0.36, 2.4, 0, TAU);
      ctx.fillStyle = "#3d3c30";
      ctx.fill();
    }
    ctx.beginPath();
    ctx.arc(0, 0, r * 0.23, 0, TAU);
    ctx.fillStyle = "#4a493a";
    ctx.fill();
    ctx.strokeStyle = "#9a9578";
    ctx.lineWidth = 1;
    ctx.stroke();

    // mud on tire
    if (truck.mud > 0.08 || w.softness > 0.2) {
      ctx.globalAlpha = Math.min(0.75, truck.mud * 0.55 + w.softness * 0.3);
      ctx.fillStyle = "#3a2b1d";
      ctx.beginPath();
      ctx.arc(0, 0, r, Math.PI * 0.1, Math.PI * 0.9);
      ctx.arc(0, 0, r * 0.72, Math.PI * 0.9, Math.PI * 0.1, true);
      ctx.fill();
      ctx.globalAlpha = 1;
    }
    ctx.restore();
  }

  drawBody(truck, r) {
    const ctx = this.ctx;

    // main silhouette
    ctx.beginPath();
    ctx.moveTo(-128, 42);
    ctx.lineTo(-132, 4);
    ctx.lineTo(-120, -32);
    ctx.lineTo(-98, -38);
    ctx.lineTo(-82, -64);
    ctx.lineTo(44, -64);
    ctx.lineTo(60, -30);
    ctx.lineTo(128, -30);
    ctx.lineTo(131, 2);
    ctx.lineTo(126, 42);
    ctx.closePath();
    const bodyGrad = ctx.createLinearGradient(0, -64, 0, 44);
    bodyGrad.addColorStop(0, "#6b7549");
    bodyGrad.addColorStop(0.35, "#5d673f");
    bodyGrad.addColorStop(0.78, "#4d5636");
    bodyGrad.addColorStop(1, "#3c442a");
    ctx.fillStyle = bodyGrad;
    ctx.fill();
    ctx.lineWidth = 1.5;
    ctx.strokeStyle = "#2c3220";
    ctx.stroke();

    // roof canvas
    ctx.beginPath();
    ctx.moveTo(-82, -64);
    ctx.quadraticCurveTo(-20, -68, 44, -64);
    ctx.lineTo(40, -58);
    ctx.quadraticCurveTo(-20, -61, -80, -58);
    ctx.closePath();
    ctx.fillStyle = "#414b2d";
    ctx.fill();
    ctx.strokeStyle = "#2b3120";
    ctx.lineWidth = 1;
    ctx.stroke();
    for (let i = 0; i < 4; i++) {
      ctx.beginPath();
      ctx.moveTo(-64 + i * 24, -64);
      ctx.lineTo(-62 + i * 24, -58);
      ctx.strokeStyle = "rgba(20, 24, 15, 0.35)";
      ctx.stroke();
    }

    // hood
    ctx.beginPath();
    ctx.moveTo(60, -30);
    ctx.lineTo(128, -30);
    ctx.lineTo(129, -22);
    ctx.lineTo(62, -22);
    ctx.closePath();
    ctx.fillStyle = "#717b4e";
    ctx.fill();
    ctx.strokeStyle = "rgba(30, 35, 20, 0.5)";
    ctx.stroke();
    // hood highlight
    ctx.strokeStyle = "rgba(225, 224, 180, 0.18)";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(64, -29);
    ctx.lineTo(126, -29);
    ctx.stroke();
    // hood latches
    ctx.fillStyle = "#2c3120";
    ctx.fillRect(116, -28, 5, 3);
    ctx.fillRect(88, -28, 5, 3);

    // windshield / side glass
    const glass = ctx.createLinearGradient(0, -62, 0, -30);
    glass.addColorStop(0, "#8fa4a2");
    glass.addColorStop(0.55, "#637a7a");
    glass.addColorStop(1, "#485c5b");
    ctx.fillStyle = glass;
    ctx.beginPath();
    ctx.moveTo(40, -58);
    ctx.lineTo(56, -32);
    ctx.lineTo(60, -32);
    ctx.lineTo(46, -60);
    ctx.closePath();
    ctx.fill();
    // front side window
    ctx.beginPath();
    ctx.moveTo(1, -58);
    ctx.lineTo(36, -58);
    ctx.lineTo(48, -34);
    ctx.lineTo(1, -34);
    ctx.closePath();
    ctx.fill();
    // rear side window
    ctx.beginPath();
    ctx.moveTo(-60, -58);
    ctx.lineTo(-6, -58);
    ctx.lineTo(-6, -34);
    ctx.lineTo(-60, -34);
    ctx.closePath();
    ctx.fill();
    // window divider
    ctx.fillStyle = "#3c452a";
    ctx.fillRect(-7, -59, 4, 26);
    // glass reflections
