    ctx.fillRect(-76, -92, 22, 22);
    ctx.strokeStyle = "#2b3120";
    ctx.lineWidth = 1.2;
    ctx.strokeRect(-76, -92, 22, 22);
    ctx.beginPath();
    ctx.moveTo(-72, -88);
    ctx.lineTo(-58, -74);
    ctx.moveTo(-72, -74);
    ctx.lineTo(-58, -88);
    ctx.stroke();
    ctx.fillStyle = "#2b3120";
    ctx.fillRect(-70, -95, 10, 4);

    // snorkel
    ctx.strokeStyle = "#23261d";
    ctx.lineWidth = 5;
    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.moveTo(58, -28);
    ctx.lineTo(56, -52);
    ctx.lineTo(49, -64);
    ctx.stroke();
    ctx.lineWidth = 3;
    ctx.strokeStyle = "#3d4132";
    ctx.beginPath();
